// === LẤY DATA ===
const sheetData = $('get imformation post1').first().json;

// Public URL ảnh từ Google Drive
const img0 = items[0]?.json?.publicImageUrl || '';
const img1 = items[1]?.json?.publicImageUrl || '';
const img2 = items[2]?.json?.publicImageUrl || '';

// === HÀM ESCAPE HTML (chỉ làm sạch ký tự đặc biệt) ===
function escapeHtml(str) {
  if (!str) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

// === ĐOẠN VĂN: tách theo DÒNG TRỐNG thành từng <p> -> khoảng cách gọn, đều nhau ===
// - dòng trống giữa các khối: KHÔNG còn tạo khoảng cách lớn, chỉ còn margin 15px
// - xuống dòng đơn trong cùng 1 khối (vd "Best regards,\nTMICORP."): vẫn giữ bằng <br>
function formatParagraph(str, style) {
  if (!str) return '';
  return String(str)
    .replace(/\r\n/g, '\n')          // chuẩn hoá xuống dòng
    .split(/\n\s*\n+/)               // tách theo dòng trống (1 hoặc nhiều dòng trống)
    .map(function (block) {
      return '<p style="' + style + '">' +
        escapeHtml(block).replace(/\n/g, '<br>') +
        '</p>';
    })
    .join('');
}

// === STYLE DÙNG CHUNG CHO ĐOẠN VĂN ===
const pStyle = 'font-size:15px; color:#3a4a5c; line-height:1.7; margin:0 0 15px; text-align:justify;';

// === TEXT TỪ SHEET (đã tự bọc <p>, KHÔNG bọc <p> bên ngoài nữa) ===
const text1 = formatParagraph(sheetData['paragraph1'], pStyle);
const text2 = formatParagraph(sheetData['paragraph2'], pStyle);
const text3 = formatParagraph(sheetData['paragraph3'], pStyle);
const subjectEmail = sheetData['subject email'] || 'TMICORP - Vietnam Agricultural Export';

// === LINK CỐ ĐỊNH ===
const websiteUrl = 'https://tmicorpgroup.com/';
const catalogUrl = 'https://drive.google.com/file/d/YOUR_GOOGLE_FILE_ID/view?usp=drive_link';
const toEmail = 'your-email@example.com';

// === HTML EMAIL ===
const html =
'<!DOCTYPE html>' +
'<html>' +
'<head>' +
'<meta charset="UTF-8">' +
'<meta name="viewport" content="width=device-width, initial-scale=1.0">' +
'<title>TMICORP</title>' +
'</head>' +
'<body style="margin:0; padding:0; background:#eef2f7; font-family:Arial,Helvetica,sans-serif;">' +
'<div style="background:#eef2f7; padding:32px 0;">' +
'<table width="100%" cellpadding="0" cellspacing="0" border="0"><tr><td align="center">' +
'<table width="600" cellpadding="0" cellspacing="0" border="0" style="background:#ffffff; border-top:4px solid #ff914d;">' +

// HEADER (thu nhỏ, chữ to hơn 1 chút)
'<tr><td style="background:#183d69; padding:7px 40px;">' +
  '<table width="100%" cellpadding="0" cellspacing="0" border="0"><tr>' +
    '<td style="vertical-align:middle;">' +
      '<p style="color:#ffffff; font-size:13px; font-weight:bold; margin:0; letter-spacing:1.5px;">TMICORP</p>' +
      '<p style="color:#a8c5e0; font-size:7px; margin:2px 0 0; letter-spacing:2px; text-transform:uppercase;">Vietnam Agricultural Processed Products</p>' +
    '</td>' +
    '<td style="vertical-align:middle; text-align:right;">' +
      '<p style="color:#ff914d; font-size:7px; margin:0; letter-spacing:1px; text-transform:uppercase; font-weight:bold;">Premium Quality</p>' +
    '</td>' +
  '</tr></table>' +
'</td></tr>' +

// BANNER ẢNH 1
'<tr><td>' +
  '<a href="' + websiteUrl + '" target="_blank" style="text-decoration:none;">' +
    '<img src="' + img0 + '" width="600" style="display:block; width:100%; border:0;" alt="TMICORP Banner">' +
  '</a>' +
'</td></tr>' +

// ACCENT BAR
'<tr><td style="background:#ff914d; height:3px; line-height:3px; font-size:0;">&nbsp;</td></tr>' +

// GREETING + ĐOẠN 1
'<tr><td style="padding:24px 40px 0 40px;">' +
  '<p style="font-size:15px; font-weight:bold; font-style:italic; color:#183d69; margin:0 0 12px;">Dear Sir/Madam,</p>' +
  text1 +
'</td></tr>' +

// ẢNH 2
'<tr><td style="padding:0 40px 15px;">' +
  '<a href="' + websiteUrl + '" target="_blank" style="text-decoration:none;">' +
    '<img src="' + img1 + '" width="520" style="display:block; width:100%; border:0;" alt="Product 1">' +
  '</a>' +
'</td></tr>' +

// ĐOẠN 2
'<tr><td style="padding:0 40px;">' +
  text2 +
'</td></tr>' +

// ẢNH 3
'<tr><td style="padding:0 40px 15px;">' +
  '<a href="' + websiteUrl + '" target="_blank" style="text-decoration:none;">' +
    '<img src="' + img2 + '" width="520" style="display:block; width:100%; border:0;" alt="Product 2">' +
  '</a>' +
'</td></tr>' +

// ĐOẠN 3
'<tr><td style="padding:0 40px;">' +
  text3 +
'</td></tr>' +

// CTA BUTTON
'<tr><td style="text-align:center; padding:6px 40px 22px;">' +
  '<a href="' + catalogUrl + '" target="_blank" style="display:inline-block; background:#ff914d; color:#ffffff; font-size:15px; font-weight:bold; padding:14px 44px; border-radius:7px; text-decoration:none; letter-spacing:0.5px;">View our catalogue &rarr;</a>' +
'</td></tr>' +

// DIVIDER
'<tr><td style="padding:0 40px;"><hr style="border:none; border-top:1px solid #eee; margin:0;"></td></tr>' +

// FOOTER
'<tr><td style="padding:20px 40px; text-align:center;">' +
  '<p style="font-size:12px; color:#aaa; margin:0 0 4px;">&copy; 2026 TMICORP &mdash; Vietnam Agricultural Processed Products</p>' +
  '<p style="font-size:12px; color:#aaa; margin:0;">' +
    '<a href="#" style="color:#aaa; text-decoration:underline;">Unsubscribe</a>' +
    ' &nbsp;|&nbsp; ' +
    '<a href="' + websiteUrl + '" style="color:#000000; text-decoration:underline; font-weight:bold;">Visit Website</a>' +
  '</p>' +
'</td></tr>' +

'</table>' +
'</td></tr></table>' +
'</div>' +
'</body>' +
'</html>';

return [{
  json: {
    htmlBody: html,
    subject: subjectEmail,
    toEmail: toEmail
  }
}];

// Tạo link ảnh nhẹ để nhúng vào email.
// Dùng endpoint thumbnail của Google Drive: Google tự resize + nén sẵn,
// nên người nhận không phải tải file gốc (có thể vài MB mỗi ảnh).
// sz=w1200 -> chiều rộng tối đa 1200px, đủ nét cho ảnh hiển thị 520-600px trong email.
// Muốn nhẹ hơn nữa thì hạ xuống w800; muốn nét hơn thì tăng lên w1600.

const WIDTH = 1200;

return items.map(item => ({
  json: {
    ...item.json,
    publicImageUrl: `https://drive.google.com/thumbnail?id=${item.json.id}&sz=w${WIDTH}`,
    originalImageUrl: `https://drive.google.com/uc?export=view&id=${item.json.id}`
  }
}));

// Gom N ảnh binary (1-10) thành 1 item duy nhất
// Tên field: attachment_1, attachment_2, ..., attachment_N
const binary = {};

items.forEach((item, index) => {
  if (item.binary?.data) {
    binary[`attachment_${index + 1}`] = item.binary.data;
  }
});

// Tạo chuỗi tên các field, phân tách bằng dấu phẩy
// Ví dụ: "attachment_1,attachment_2,attachment_3"
const attachmentFields = Object.keys(binary).join(',');

return [{
  json: {
    ready: true,
    attachmentCount: Object.keys(binary).length,
    attachmentFields: attachmentFields  // ← QUAN TRỌNG: dùng cho Gmail node
  },
  binary: binary
}];
